class Agent:
    def __init__(self, name):
        self.name = name
        self.hp = 100

    def take_damage(self, damage):
        self.hp -= damage
        return self.hp

a = Agent("V")
print(a.take_damage(30))  # 70
print(a.hp)  # 70

